<?php $token = $escape($_SESSION['_token']); ?>
<section class="card"><div class="card-header"><h2>Zone deployment matrix</h2><p class="small text-secondary mb-0">Acknowledged revisions reflect the last successful local authoritative SOA check. Stale member health is shown separately.</p></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Member / domain</th><th>Desired</th><th>Applied</th><th>Sync</th><th>Signatures expire</th><th>Last verified</th></tr></thead><tbody><?php foreach ($deployments as $d): $synced = $d['applied_revision'] !== null && (int) $d['applied_revision'] === (int) $d['desired_revision']; $fresh = $d['health_at'] && strtotime($d['health_at'] . ' UTC') > time() - 300; ?><tr><td><strong><?= $escape($d['server_name']) ?></strong><div class="small"><?= $escape($d['zone_name']) ?></div><?php if ($d['last_error']): ?><div class="small text-danger"><?= $escape($d['last_error']) ?></div><?php endif; ?></td><td>r<?= (int) $d['desired_revision'] ?></td><td><?= $d['applied_revision'] ? 'r' . (int) $d['applied_revision'] : '—' ?></td><td><span class="badge <?= $synced ? 'text-bg-success' : 'text-bg-warning' ?>"><?= $synced ? 'Synced' : 'Pending' ?></span><?php if (!$fresh): ?><div class="small text-warning-emphasis">Health stale</div><?php endif; ?></td><td class="small"><?= $escape($d['signed_until'] ?? '—') ?></td><td class="small"><?= $escape($d['verified_at'] ?? 'Not verified') ?></td></tr><?php endforeach; ?><?php if (!$deployments): ?><tr><td colspan="6" class="empty-state">Publish a zone and onboard a member to see deployment status.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="card mt-4"><div class="card-header"><h2>Job history</h2></div><div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>Operation</th><th>State</th><th>Attempts</th><th>Available</th><th>Last error</th></tr></thead><tbody><?php foreach ($jobs as $job): ?><tr><td><?= (int) $job['id'] ?></td><td><?= $escape($job['kind']) ?></td><td><?= $escape($job['state']) ?></td><td><?= (int) $job['attempts'] ?></td><td class="small"><?= $escape($job['available_at']) ?></td><td class="small text-danger error-cell"><?= $escape($job['last_error'] ?? '') ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="card mt-4"><div class="card-header"><h2>Administrative audit</h2></div><div class="table-responsive"><table class="table"><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Subject</th><th>Details</th></tr></thead><tbody><?php foreach ($events as $event): ?><tr><td class="small"><?= $escape($event['created_at']) ?></td><td><?= $escape($event['actor']) ?></td><td><?= $escape($event['action']) ?></td><td><?= $escape($event['subject']) ?></td><td class="small error-cell"><?= $escape($event['details']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
